using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SleepyPillowOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/SleepyPillow Omen Data")]
public class SleepyPillowOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.SleepyPillowOmenAction = delegate(int effectAmount)
		{
			omenInstance.ActivateOmenFeedback();
			return effectAmount + ActionValue;
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.SleepyPillowOmenAction = null;
	}
}
